document.addEventListener("alpine:init",()=>{Alpine.data("otpCode",(v,len=8,reg=/[1-9A-Za-z]/)=>({input:0,otp_length:len,value:v||"",otp_regex:reg,get inputs(){return this.$refs.otpInputContainer.querySelectorAll(".otpInput")},init(){this.$nextTick(()=>{this.inputs?.[0]?.focus(),this.setInput(this.value)})},validateKeyPress(e){(e.ctrlKey||e.metaKey)&&"v"===e.key||["Backspace","Tab","ArrowLeft","ArrowRight"].includes(e.key)||this.otp_regex.test(e.key)||e.preventDefault()},handleInput(e,index){var match=e.target.value.match(this.otp_regex),match=match?match[0]:"",e=(e.target.value=match,[...this.inputs].map(input=>input.value));this.value=e.join(""),match&&(e=this.inputs[index+1])&&(e.focus(),e.select())},setInput(v){[...(v||"").replace(new RegExp(`[^${this.otp_regex.source}]`,"g"),"").slice(0,this.otp_length)].forEach((char,i)=>{this.inputs[i]&&(this.inputs[i].value=char)}),this.value=[...this.inputs].map(input=>input.value).join("")},handlePaste(e){e.preventDefault();e=(e.clipboardData.getData("text")||"").split("").filter(ch=>(this.otp_regex.lastIndex=0,this.otp_regex.test(ch))).join("").slice(0,this.otp_length),this.setInput(e),e=[...this.inputs].findIndex(input=>!input.value),e=-1===e?this.otp_length-1:e;this.inputs[e]?.focus()},handleBackspace(e,index){0<index&&(this.inputs[index-1].focus(),this.inputs[index-1].select())}}))});